def transform(grid):
    # Identify boundary diagonal marks and fill their interior with color 2.
    out = [row[:] for row in grid]
    marks = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    if not marks:
        return out
    # Demo establishes a triangular region bounded by diagonals: rows of marks
    # are outer edge, with fill between left and right marks, shifted inward.
    # Use rays/line positions per row and fill between the two edge markers.
    byrow = {}
    for r,c in marks:
        byrow.setdefault(r, []).append(c)
    for r, cols in byrow.items():
        if len(cols) >= 2:
            for c in range(min(cols)+1, max(cols)):
                if out[r][c] == 0: out[r][c] = 2
    return out
